def replace_extension(path, new_ext):
    """Return path with its extension replaced by new_ext (including dot). If path has no extension, append new_ext.
    Only the last dot is considered, and leading dots in basename are ignored (hidden files). Empty path returns new_ext.
    Example: replace_extension('dir/file.txt', '.md') -> 'dir/file.md'"""
    if not path:
        return new_ext
    (base, sep, ext) = path.rpartition('.')
    if sep == '' or base == '' or base.endswith('/') or base.endswith('\\'):
        return path + new_ext
    return base + sep + new_ext

