def apply_discount_sequence(prices, discounts):
    """Applies each discount rate (as a fraction, e.g. 0.1 for 10%) in order to a list of prices, mutating the list in place. Returns the modified list. For empty prices, returns the empty list. If discount list is longer than prices, extra discounts are ignored. Example: apply_discount_sequence([100, 50], [0.1, 0.2]) -> [90.0, 40.0]"""
    if not prices:
        return prices
    for i in range(min(len(prices), len(discounts))):
        prices[i] = prices[i] * (1 - discounts[i])
    return prices

for args in [([], [0.1],), ([100, 50], [0.1, 0.2],), ([50, 60, 70], [0.2],)]:
