def update_stock(stock, item, delta):
    """Adjust quantity for item in stock dict (in-place).
    Returns the new quantity for that item. Missing item is set to delta.
    If resulting quantity negative, clamp to zero and return 0.
    Example: update_stock(dict(a=5), 'a', -2) -> 3"""
    if item in stock:
        new_qty = stock[item] + delta
    else:
        new_qty = delta
    if new_qty < 0:
        new_qty = 0
    stock[item] = new_qty
    return new_qty

