    """Return the length of the longest strictly increasing subsequence.
    For empty list, return 0. Single element returns 1. Ties not allowed (strict >).
    Example: lis_length([3, 1, 4, 1, 5, 9, 2, 6]) -> 4."""
    tails = []
    for x in nums:
        i = 0
        j = len(tails)
        while i < j:
            m = (i + j) // 2
            if tails[m] < x:
                i = m + 1
            else:
                j = m
        if i == len(tails):
            tails.append(x)
        else:
            tails[i] = x
    return len(tails)

