def tie_break_alphabetical(players):
    """Return list of player names sorted by score descending, and for ties alphabetically by name (case-sensitive, uppercase before lowercase). For empty list return empty list. Example: tie_break_alphabetical([('bob', 5), ('Alice', 5)]) -> ['Alice', 'bob']"""
    if not players:
