def truncate_middle(s, max_len, ellipsis='...'):
    if len(s) <= max_len or max_len <= 0:
        return s[:max_len] if max_len > 0 else ''
    if len(ellipsis) >= max_len:
        return s[:max_len]
    keep = max_len - len(ellipsis)
    left_len = (keep + 1) // 2
    right_len = keep // 2
    return s[:left_len] + ellipsis + s[-right_len:] if right_len >= 0 else s[:left_len] + ellipsis

