def cumulative_sum_bounded(values, low, high):
    """Return list of cumulative sums, but each sum is clamped to [low, high] before adding next.
    If empty input, return empty list. Single element: clamped once.
    Clamping uses inclusive bounds. Example: cumulative_sum_bounded([2, 3, -5], 0, 4) -> [2, 4, 0]"""
    if not values:
        return []
    result = []
    acc = 0
    for v in values:
        acc += v
        if acc < low:
            acc = low
        elif acc > high:
            acc = high
        result.append(acc)
    return result

