    """Split a CSV line into a list of strings. Handles double quotes and commas inside quotes. Empty input returns an empty list. Example: parse_csv_line('a,"b,c"') -> ['a', 'b,c'].
    """
    if not line:
        return []
    result = []
    current = ''
    in_quotes = False
    i = 0
    while i < len(line):
        char = line[i]
        if in_quotes:
