def calculate_order_total(order_lines, price_list):
    """Calculate total price for order lines given price_list as list of (item, price) tuples. Returns float total. If order_lines empty returns 0.0. Example: calculate_order_total([('apple',3)], [('apple',1.5)]) -> 4.5"""
    total = 0.0
    for (item, qty) in order_lines:
        found = False
        for (name, price) in price_list:
