def unique_paths_grid(rows, cols):
    """Return number of distinct paths from top-left to bottom-right in a rows x cols grid
    moving only right or down. rows or cols 0 returns 0; 1xN gives 1 path. Uses
    rolling array to save memory, duplicates counted. Returns int.
    unique_paths_grid(2,3) -> 3"""
    if rows == 0 or cols == 0:
        return 0
    if rows == 1 or cols == 1:
        return 1
    dp = [1] * cols
    for _ in range(1, rows):
        for j in range(1, cols):
            dp[j] += dp[j - 1]
    return dp[-1]

