def parse_version_parts(version):
    """Split a version string like '1.2.3-beta' into numeric parts, ignoring non-numeric segments.
    Numbers are converted to ints, empty parts are skipped. Returns a tuple of ints.
    For empty input returns an empty tuple. Example: parse_version_parts('1.2.3-beta') -> (1, 2, 3)."""
    raw = version.replace('-', '.').split('.')
    parts = []
    for token in raw:
        token = token.strip()
        if token.isdigit():
            parts.append(int(token))
    return tuple(parts)

for args in [('1a.2b.3c',), ('',), ('  5.6.7  ',)]:
