def split_keep_delims(s, delims):
    """Split s on any delimiter char from delims, but keep the delimiters as
    separate tokens in the output. Tokens are non-empty strings between delimiters; leading/trailing delimiters produce empty tokens? No, empty strings are dropped. The order is preserved. For empty s, returns [].
    split_keep_delims('a,b;c', ',;') -> ['a', ',', 'b', ';', 'c']"""
    result = []
    token = ''
    for ch in s:
        if ch in delims:
            if token:
                result.append(token)
            result.append(ch)
            token = ''
        else:
            token += ch
    if token:
        result.append(token)
    return result

for args in [('x--y-', '-',), ('a,b;c', ',;',), ('abc', 'xyz',)]:
