def schrikkel(j):
    return j % 4 == 0 and (j % 100 != 0 or j % 400 == 0)

def dagnr(j, m, d):
    lengtes = [31, 29 if schrikkel(j) else 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
    vorige = j - 1
    dagen = vorige * 365 + vorige // 4 - vorige // 100 + vorige // 400
    return dagen + sum(lengtes[:m - 1]) + d

