def mask_card(number):
    total = sum(c.isdigit() for c in number)
    out, seen = [], 0
    for c in number:
        if c.isdigit():
            seen += 1
            out.append(c if seen > total - 4 else '*')
        else:
            out.append(c)
    return ''.join(out)

