def split_ext_once(filename):
    """Split a filename into (base, extension) at the last dot. Extension is
    '.' plus the suffix, or empty string if no dot. Base excludes the dot. For
    hidden files like '.bashrc', treat as no extension. For empty string,
    return ('', ''). Example: split_ext_once('archive.tar.gz') -> ('archive.tar', '.gz')"""
    if not filename:
        return ('', '')
    if filename.startswith('.'):
        return (filename, '')
    (base, sep, ext) = filename.rpartition('.')
    if sep:
        return (base, '.' + ext)
    else:
        return (filename, '')

