def word_wrap(text, max_width, break_long_words=True):
    """Return a list of lines such that each line (except possibly the last) is as long as possible without exceeding max_width. Words are split by single spaces; existing multiple spaces collapse to one. If a single word longer than max_width and break_long_words is True, it's broken at max_width chunks; otherwise it stays on its own line. Empty text returns []. Example: word_wrap('a bb ccc', 4) -> ['a bb', 'ccc']."""
    if not text:
        return []
    words = text.split(' ')
    words = [w for w in words if w != '']
    lines = []
    current = ''
    for w in words:
        if len(w) > max_width and break_long_words:
            if current:
                lines.append(current)
                current = ''
            while len(w) > max_width:
                lines.append(w[:max_width])
                w = w[max_width:]
            current = w
        else:
            if not current:
                candidate = w
            else:
                candidate = current + ' ' + w
            if len(candidate) <= max_width:
                current = candidate
            else:
                lines.append(current)
                current = w
    if current or not lines:
        lines.append(current)
    return lines

print(word_wrap('supercalifragilistic', 5))

