def join_csv_fields(fields):
    """Join a list of strings into a CSV line, quoting only fields containing comma, quote, or newline. Empty list returns an empty string. Example: join_csv_fields(['a','b,c']) -> 'a,"b,c"'. Preserves order.
    """
    if not fields:
        return ''
    out = []
    for field in fields:
        if ',' in field or '"' in field or '\n' in field:
            out.append('"' + field.replace('"', '""') + '"')
