def sort_by_average_grade_ties(students):
    """Sort list of (name, grades) tuples by average grade descending, then by name ascending. Use integer division for average (floor), not float. Ties in both average and name preserve original order (stable). Empty list returns []. Example: sort_by_average_grade_ties([('A',[10,20]),('B',[15,15])]) -> [('B',[15,15]),('A',[10,20])] because B avg 15, A avg 10."""

    def key(item):
        (name, grades) = item
        return (-(sum(grades) // len(grades)), name)
    return sorted(students, key=key)

