def sort_by_last_word(words):
    """Sort strings by their last whitespace-separated word, then by the whole string.
    Input: list of non-empty strings (may contain spaces). Output: new list sorted ascending.
    Tie: if last words equal, tie-break by full string lexicographically. Empty input -> empty list.
    Example: sort_by_last_word(['apple pie', 'cherry', 'banana']) -> ['banana', 'cherry', 'apple pie']
    Uses split() default whitespace, last element via key[1], None-safe? Not needed here."""

    def key(s):
        parts = s.split()
        if not parts:
            return ('', '')
        return (parts[-1].lower(), s.lower())
    return sorted(words, key=key)

